"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Sweet as Rosewood', 'author': 'Signature original', 'genre': 'Small Town Romance', 'chapters': [{'n': 1, 'title': 'Homecoming', 'text': "He was there — the boy from that summer, grown into a man with the same laugh. Time folded. Lucy Fairbanks's heart, so carefully guarded, did something reckless: it hoped.\n\nThat evening she walked to the shore, a vintage locket in her pocket. The sunset did what Rosewood sunsets always did: made her feel everything at once. She wasn't alone long.\n\nher sister Lily met her at the station with a hug that smelled of Rosewood: salt, wildflowers, fresh bread. 'You look like you need pie,' her sister Lily said, which was her sister Lily's diagnosis for everything, and usually right."}, {'n': 2, 'title': 'The Thing Remembered', 'text': "He found her at the bookshop, reaching for the same novel. Their hands touched. The whole shop seemed to hold its breath. 'You came back,' he said, and it wasn't a question, it was a prayer answered.\n\nThey talked until the shop closed, until the streetlights came on in Rosewood. Seventeen years of almosts poured out: the almost-letters, the almost-calls, the life they'd almost shared.\n\na vintage locket turned out to be a map of sorts: a letter never sent, a promise never kept. Lucy Fairbanks read it on the porch swing while Rosewood hummed around her, and cried the good kind of crying."}, {'n': 3, 'title': 'Complications', 'text': "Of course it couldn't be simple. her ex Daniel reappeared — older, smoother, with apologies like gift wrap. 'I've changed,' her ex Daniel said, and for an hour Lucy Fairbanks almost believed it.\n\nHe — the bookshop man, the summer boy — went quiet. Not angry, just hurt, in the way of someone who's waited seventeen years and can wait no longer. Lucy Fairbanks felt the old panic rise: run, before it breaks.\n\nHer grandmother Rose's voice came back to her: 'The heart knows first, baby. The head just takes minutes.' Lucy Fairbanks stopped running. She turned around and went to find him."}, {'n': 4, 'title': 'The Choice', 'text': "her sister Lily cried at the news and denied it. The whole of Rosewood seemed to conspire in their happiness: the bookshop stayed open late, the bakery made a cake, the wildflowers bloomed on schedule.\n\nShe found him at the shore, where it started. 'I choose,' she said, breathless, 'the thing that scares me. I choose you. I've always chosen you — I just took seventeen years to say it.'\n\nher ex Daniel left town with the gift wrap and the almosts. Lucy Fairbanks felt nothing but pity — and then not even that, because her arms were full of present tense."}, {'n': 5, 'title': 'The Promise', 'text': "The wedding was in Rosewood, in the season of wildflowers. Her grandmother Rose's quilt was on the bed. her sister Lily gave a speech that made everyone cry laughing.\n\nhome is a person — Lucy Fairbanks wrote it in the new journal, the one for the next seventeen years. In Rosewood, under the stars, with love: the whole story, and only just beginning.\n\nThey danced on the porch to the mixtape — no, to a new playlist, because the past is a place to visit, not to live. Lucy Fairbanks had learned that at last."}, {'n': 6, 'title': 'Epilogue in Wildflowers', 'text': "Years later, a vintage locket sits on the mantel still, a little faded, entirely cherished. The house is full of noise: children, dogs, her sister Lily's children, the whole beautiful chaos of a life chosen.\n\nher sister Lily still diagnoses everything with pie. Her grandmother Rose's quilt is worn thin with love. her ex Daniel is a story they tell laughing, a ghost with no haunting left in it.\n\nAnd when the children ask about a vintage locket, Lucy Fairbanks tells them: it was a map. Not to a place — to a person. To the bravest thing she ever did, which was to come home."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

